const html = "<!doctype html>\n<html lang=\"es\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta\n      name=\"description\"\n      content=\"VAPA, una app web para encontrar, organizar y solicitar becas paso a paso.\"\n    />\n    <title>VAPA | Becas</title>\n    <style>:root {\n  color-scheme: light;\n  --bg: #f6d2ff;\n  --bg-deep: #e8b7ff;\n  --panel: rgba(255, 255, 255, 0.74);\n  --panel-strong: rgba(255, 255, 255, 0.88);\n  --text: #24152f;\n  --muted: #5f4d6b;\n  --primary: #6d28d9;\n  --primary-2: #8a3be8;\n  --primary-3: #b26bff;\n  --line: rgba(99, 48, 149, 0.14);\n  --shadow: 0 24px 60px rgba(95, 37, 134, 0.18);\n  --radius-xl: 34px;\n  --radius-lg: 24px;\n  --radius-md: 18px;\n  --radius-sm: 12px;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  margin: 0;\n  font-family: \"Avenir Next\", \"Segoe UI\", \"Trebuchet MS\", sans-serif;\n  color: var(--text);\n  background:\n    radial-gradient(circle at 18% 12%, rgba(255, 255, 255, 0.55), transparent 20%),\n    radial-gradient(circle at 82% 18%, rgba(255, 255, 255, 0.32), transparent 19%),\n    radial-gradient(circle at 50% 90%, rgba(255, 255, 255, 0.24), transparent 22%),\n    linear-gradient(180deg, #e5a9fb 0%, var(--bg) 34%, #f7dfff 100%);\n  min-height: 100vh;\n  overflow-x: hidden;\n}\n\na {\n  color: inherit;\n  text-decoration: none;\n}\n\nbutton,\ninput,\nselect {\n  font: inherit;\n}\n\n.page-noise,\n.page-glow {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n}\n\n.page-noise {\n  opacity: 0.08;\n  background-image:\n    linear-gradient(rgba(255, 255, 255, 0.3) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(255, 255, 255, 0.3) 1px, transparent 1px);\n  background-size: 76px 76px;\n  mask-image: radial-gradient(circle at center, black 52%, transparent 100%);\n}\n\n.page-glow-left {\n  background: radial-gradient(circle, rgba(255, 255, 255, 0.36), transparent 52%);\n  width: 40vw;\n  height: 40vw;\n  top: -10vw;\n  left: -12vw;\n  filter: blur(28px);\n}\n\n.page-glow-right {\n  background: radial-gradient(circle, rgba(255, 255, 255, 0.22), transparent 54%);\n  width: 32vw;\n  height: 32vw;\n  top: 12vw;\n  right: -10vw;\n  filter: blur(28px);\n}\n\n.topbar,\n.layout,\n.footer {\n  position: relative;\n  z-index: 1;\n}\n\n.topbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 24px;\n  padding: 22px clamp(20px, 4vw, 48px);\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.brand-mark {\n  width: 54px;\n  height: 54px;\n  border-radius: 18px;\n  display: grid;\n  place-items: center;\n  background: linear-gradient(145deg, #fff, #edd5ff);\n  color: var(--primary);\n  font-weight: 900;\n  font-size: 1.6rem;\n  box-shadow: 0 12px 28px rgba(96, 24, 134, 0.15);\n}\n\n.eyebrow,\n.section-kicker,\n.small-label {\n  margin: 0;\n  text-transform: uppercase;\n  letter-spacing: 0.16em;\n  font-size: 0.72rem;\n  color: var(--primary);\n  font-weight: 800;\n}\n\n.brand h1,\n.hero h2,\n.panel h3 {\n  margin: 0;\n}\n\n.brand h1 {\n  font-size: 1.55rem;\n  line-height: 1;\n}\n\n.topnav {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  flex-wrap: wrap;\n  padding: 10px 14px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.42);\n  border: 1px solid rgba(255, 255, 255, 0.5);\n  box-shadow: 0 12px 24px rgba(89, 28, 138, 0.08);\n  backdrop-filter: blur(12px);\n}\n\n.topnav a {\n  color: var(--muted);\n  font-size: 0.95rem;\n  font-weight: 700;\n}\n\n.layout {\n  width: min(1280px, calc(100% - 32px));\n  margin: 0 auto;\n  padding: 6px 0 44px;\n}\n\n.hero {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) minmax(360px, 0.9fr);\n  gap: 28px;\n  align-items: center;\n  margin: 8px 0 30px;\n}\n\n.hero-copy {\n  padding: 18px 8px 18px 0;\n}\n\n.pill,\n.mini-badge {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 10px 16px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.58);\n  border: 1px solid rgba(255, 255, 255, 0.6);\n  color: var(--primary);\n  font-size: 0.95rem;\n  font-weight: 700;\n  box-shadow: 0 10px 24px rgba(100, 45, 144, 0.08);\n}\n\n.hero h2 {\n  margin-top: 18px;\n  font-size: clamp(2.4rem, 3.8vw, 4.8rem);\n  line-height: 0.95;\n  letter-spacing: -0.04em;\n  max-width: 12ch;\n}\n\n.lead,\n.panel-text,\n.step-card p,\n.stack-list span,\n.source-card p,\n.action-grid p {\n  color: var(--muted);\n  line-height: 1.6;\n}\n\n.lead {\n  font-size: 1.06rem;\n  max-width: 62ch;\n  margin: 18px 0 0;\n}\n\n.cta-row,\n.phone-actions {\n  display: flex;\n  gap: 14px;\n  flex-wrap: wrap;\n}\n\n.cta-row {\n  margin-top: 26px;\n}\n\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 52px;\n  padding: 0 22px;\n  border-radius: 18px;\n  border: 1px solid transparent;\n  font-weight: 800;\n  cursor: pointer;\n  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;\n}\n\n.btn:hover,\n.filter-btn:hover,\n.menu-card:hover,\n.dock-item:hover {\n  transform: translateY(-2px);\n}\n\n.btn-primary {\n  background: linear-gradient(135deg, var(--primary), var(--primary-2));\n  color: white;\n  box-shadow: 0 16px 34px rgba(106, 36, 176, 0.28);\n}\n\n.btn-secondary {\n  background: rgba(255, 255, 255, 0.6);\n  color: var(--text);\n  border-color: rgba(103, 57, 142, 0.1);\n}\n\n.stat-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 14px;\n  margin-top: 26px;\n  max-width: 520px;\n}\n\n.stat-card,\n.panel,\n.source-card,\n.action-grid article {\n  background: var(--panel);\n  border: 1px solid rgba(255, 255, 255, 0.68);\n  box-shadow: var(--shadow);\n  backdrop-filter: blur(16px);\n}\n\n.stat-card {\n  border-radius: 22px;\n  padding: 18px;\n  min-height: 100px;\n}\n\n.stat-card strong {\n  display: block;\n  font-size: 1.8rem;\n  color: var(--primary);\n}\n\n.stat-card span {\n  color: var(--muted);\n}\n\n.phone-stage {\n  position: relative;\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 18px;\n  justify-items: center;\n  align-items: center;\n}\n\n.phone {\n  width: 100%;\n  max-width: 354px;\n  border-radius: 42px;\n  padding: 10px;\n  background: linear-gradient(180deg, #f7f7f7, #f0e9f7);\n  box-shadow:\n    0 20px 30px rgba(44, 10, 77, 0.18),\n    inset 0 0 0 1px rgba(255, 255, 255, 0.9);\n}\n\n.phone-left {\n  transform: translateY(-14px);\n}\n\n.phone-right {\n  transform: translateY(24px);\n}\n\n.phone-notch {\n  width: 36%;\n  height: 18px;\n  margin: 6px auto 10px;\n  border-radius: 0 0 18px 18px;\n  background: rgba(0, 0, 0, 0.88);\n}\n\n.screen {\n  min-height: 690px;\n  padding: 22px 18px 18px;\n  border-radius: 34px;\n  background: linear-gradient(180deg, #f4f2f6, #faf8fc 45%, #f3eef8);\n  display: flex;\n  flex-direction: column;\n}\n\n.welcome-screen {\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  gap: 18px;\n}\n\n.logo-stack {\n  display: grid;\n  justify-items: center;\n  gap: 10px;\n}\n\n.mortarboard {\n  position: relative;\n  width: 132px;\n  height: 88px;\n  margin-bottom: 8px;\n}\n\n.cap {\n  position: absolute;\n  left: 50%;\n  top: 4px;\n  width: 126px;\n  height: 0;\n  border-left: 64px solid transparent;\n  border-right: 64px solid transparent;\n  border-bottom: 26px solid #111;\n  transform: translateX(-50%);\n}\n\n.cap::before {\n  content: \"\";\n  position: absolute;\n  left: -42px;\n  top: 23px;\n  width: 84px;\n  height: 24px;\n  background: #111;\n  border-radius: 0 0 10px 10px;\n  box-shadow: inset 0 -6px 0 #5e2ca5;\n}\n\n.tassel {\n  position: absolute;\n  left: 35px;\n  top: 18px;\n  width: 12px;\n  height: 56px;\n  background: linear-gradient(180deg, #5b21b6, #8a3be8);\n  border-radius: 10px;\n  transform: rotate(20deg);\n}\n\n.welcome-title {\n  color: var(--primary);\n  font-size: clamp(3rem, 8vw, 4.3rem);\n  line-height: 0.9;\n  font-weight: 900;\n  letter-spacing: -0.06em;\n}\n\n.welcome-subtitle {\n  margin: 0;\n  color: #6b4d93;\n  font-size: 1rem;\n}\n\n.welcome-body {\n  margin: 14px 0 4px;\n  color: #2f203e;\n  font-size: 1.02rem;\n  font-weight: 700;\n  max-width: 18ch;\n}\n\n.dashboard-screen {\n  gap: 16px;\n}\n\n.dashboard-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.dashboard-head h3 {\n  font-size: 2rem;\n  line-height: 1;\n  color: var(--primary);\n  letter-spacing: -0.05em;\n}\n\n.heart {\n  font-size: 2rem;\n  color: #2e143d;\n  transform: rotate(-8deg);\n}\n\n.grid-menu {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 12px;\n  flex: 1;\n}\n\n.menu-card {\n  min-height: 116px;\n  border-radius: 18px;\n  padding: 16px 12px;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n  text-align: center;\n  gap: 8px;\n  box-shadow: 0 14px 24px rgba(90, 33, 138, 0.08);\n  color: #17101f;\n  font-size: 0.95rem;\n  font-weight: 800;\n}\n\n.menu-icon {\n  font-size: 1.8rem;\n}\n\n.blue {\n  background: #c5e8ff;\n}\n\n.green {\n  background: #d5f4b7;\n}\n\n.lilac {\n  background: #f3d1ff;\n}\n\n.yellow {\n  background: #ffedb2;\n}\n\n.mint {\n  background: #c9f8df;\n}\n\n.sky {\n  background: #c6ebff;\n}\n\n.bottom-dock {\n  margin-top: auto;\n  display: flex;\n  justify-content: space-around;\n  gap: 10px;\n  padding: 12px 4px 0;\n  border-top: 1px solid rgba(105, 63, 146, 0.12);\n}\n\n.dock-item {\n  color: #2d213a;\n  font-weight: 700;\n  font-size: 0.98rem;\n}\n\n.dock-item.active {\n  color: var(--primary);\n}\n\n.content-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 22px;\n  margin-top: 22px;\n}\n\n.panel {\n  border-radius: var(--radius-xl);\n  padding: 24px;\n}\n\n.panel-head {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  margin-bottom: 18px;\n}\n\n.panel-head.split {\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 16px;\n  flex-direction: row;\n}\n\n.panel-head h3 {\n  font-size: clamp(1.4rem, 2vw, 2.1rem);\n  letter-spacing: -0.03em;\n}\n\n.timeline,\n.stack-list,\n.checklist {\n  display: grid;\n  gap: 12px;\n}\n\n.step-card,\n.stack-list > div,\n.checklist-item {\n  border-radius: 20px;\n  background: rgba(255, 255, 255, 0.72);\n  border: 1px solid rgba(110, 60, 164, 0.08);\n  padding: 14px 16px;\n}\n\n.step-card {\n  display: grid;\n  grid-template-columns: 52px minmax(0, 1fr);\n  gap: 14px;\n  align-items: start;\n}\n\n.step-card span {\n  width: 52px;\n  height: 52px;\n  border-radius: 16px;\n  display: grid;\n  place-items: center;\n  background: linear-gradient(145deg, var(--primary), var(--primary-3));\n  color: white;\n  font-weight: 900;\n  font-size: 1.15rem;\n}\n\n.step-card strong,\n.stack-list strong,\n.source-card strong,\n.action-grid strong {\n  display: block;\n  margin-bottom: 4px;\n}\n\n.profile-form {\n  display: grid;\n  gap: 14px;\n}\n\n.profile-form label {\n  display: grid;\n  gap: 8px;\n  font-size: 0.9rem;\n  font-weight: 800;\n  color: #4f365f;\n}\n\n.profile-form input,\n.profile-form select,\n.search-box input {\n  width: 100%;\n  border: 1px solid rgba(101, 61, 145, 0.14);\n  background: rgba(255, 255, 255, 0.74);\n  border-radius: 16px;\n  padding: 14px 16px;\n  color: var(--text);\n  outline: none;\n}\n\n.profile-form input:focus,\n.profile-form select:focus,\n.search-box input:focus {\n  border-color: rgba(109, 40, 217, 0.38);\n  box-shadow: 0 0 0 4px rgba(141, 84, 233, 0.12);\n}\n\n.profile-note {\n  margin-top: 16px;\n  padding: 16px 18px;\n  border-radius: 20px;\n  background: linear-gradient(135deg, rgba(109, 40, 217, 0.12), rgba(178, 107, 255, 0.12));\n  color: #402356;\n  font-weight: 700;\n}\n\n.profile-chips,\n.quick-filters,\n.tag-cloud {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.profile-chips {\n  margin-top: 14px;\n}\n\n.profile-chips span,\n.tag-cloud span {\n  padding: 10px 14px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.74);\n  border: 1px solid rgba(101, 61, 145, 0.08);\n  color: #4f365f;\n  font-weight: 700;\n}\n\n.quick-filters {\n  margin-bottom: 18px;\n}\n\n.filter-btn {\n  border: 1px solid rgba(109, 40, 217, 0.14);\n  background: rgba(255, 255, 255, 0.68);\n  color: #4d3564;\n  border-radius: 999px;\n  padding: 10px 16px;\n  font-weight: 800;\n  cursor: pointer;\n  transition: transform 160ms ease, background 160ms ease, color 160ms ease;\n}\n\n.filter-btn.active {\n  color: white;\n  background: linear-gradient(135deg, var(--primary), var(--primary-2));\n  box-shadow: 0 12px 22px rgba(109, 40, 217, 0.2);\n}\n\n.cards-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.scholarship-card {\n  border-radius: 24px;\n  padding: 18px;\n  background: rgba(255, 255, 255, 0.74);\n  border: 1px solid rgba(110, 60, 164, 0.08);\n  box-shadow: 0 18px 32px rgba(90, 33, 138, 0.08);\n}\n\n.scholarship-card h4 {\n  margin: 0 0 8px;\n  font-size: 1.1rem;\n}\n\n.meta-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-bottom: 12px;\n}\n\n.meta-row span {\n  font-size: 0.78rem;\n  font-weight: 800;\n  color: #5a3b77;\n  background: rgba(112, 56, 168, 0.08);\n  border-radius: 999px;\n  padding: 6px 10px;\n}\n\n.source-row,\n.action-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 14px;\n  margin-top: 18px;\n}\n\n.source-card {\n  border-radius: 24px;\n  padding: 18px;\n}\n\n.blue-soft {\n  background: rgba(195, 233, 255, 0.68);\n}\n\n.green-soft {\n  background: rgba(212, 244, 183, 0.68);\n}\n\n.lilac-soft {\n  background: rgba(243, 209, 255, 0.72);\n}\n\n.checklist-item {\n  display: flex;\n  gap: 12px;\n  align-items: center;\n}\n\n.checklist-item input {\n  width: 20px;\n  height: 20px;\n  accent-color: var(--primary);\n}\n\n.checklist-item p {\n  margin: 0;\n}\n\n.stack-list > div {\n  display: grid;\n  gap: 4px;\n}\n\n.action-grid article {\n  border-radius: 24px;\n  padding: 18px;\n}\n\n.footer {\n  width: min(1280px, calc(100% - 32px));\n  margin: 18px auto 34px;\n  padding: 18px 24px;\n  border-radius: 28px;\n  background: rgba(255, 255, 255, 0.62);\n  border: 1px solid rgba(255, 255, 255, 0.62);\n  box-shadow: 0 18px 40px rgba(90, 33, 138, 0.09);\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 18px;\n}\n\n.reveal {\n  animation: rise 700ms ease both;\n}\n\n@keyframes rise {\n  from {\n    opacity: 0;\n    transform: translateY(14px);\n  }\n\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n@media (max-width: 1120px) {\n  .hero,\n  .content-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .phone-stage {\n    grid-template-columns: 1fr 1fr;\n  }\n\n  .cards-grid,\n  .source-row,\n  .action-grid {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 760px) {\n  .topbar {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n\n  .topnav {\n    width: 100%;\n    justify-content: space-between;\n  }\n\n  .layout {\n    width: min(100% - 18px, 1280px);\n    padding-top: 0;\n  }\n\n  .hero {\n    gap: 20px;\n  }\n\n  .hero-copy {\n    padding-right: 0;\n  }\n\n  .stat-grid,\n  .cards-grid,\n  .source-row,\n  .action-grid,\n  .phone-stage {\n    grid-template-columns: 1fr;\n  }\n\n  .phone-left,\n  .phone-right {\n    transform: none;\n  }\n\n  .phone {\n    max-width: 100%;\n  }\n\n  .screen {\n    min-height: auto;\n  }\n\n  .panel {\n    padding: 20px;\n  }\n\n  .panel-head.split {\n    flex-direction: column;\n  }\n\n  .footer {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n}\n</style>\n  </head>\n  <body>\n    <div class=\"page-noise\"></div>\n    <div class=\"page-glow page-glow-left\"></div>\n    <div class=\"page-glow page-glow-right\"></div>\n\n    <header class=\"topbar\">\n      <div class=\"brand\">\n        <div class=\"brand-mark\">V</div>\n        <div>\n          <p class=\"eyebrow\">Visualiza \u2022 Aprende \u2022 Progresa \u2022 Avanza</p>\n          <h1>VAPA</h1>\n        </div>\n      </div>\n\n      <nav class=\"topnav\" aria-label=\"Secciones principales\">\n        <a href=\"#inicio\">Inicio</a>\n        <a href=\"#intro\">Gu\u00eda</a>\n        <a href=\"#perfil\">Perfil</a>\n        <a href=\"#buscar\">Buscar</a>\n        <a href=\"#documentos\">Documentos</a>\n      </nav>\n    </header>\n\n    <main class=\"layout\">\n      <section class=\"hero\" id=\"inicio\">\n        <div class=\"hero-copy reveal\">\n          <span class=\"pill\">Tu espacio para crecer, aprender y alcanzar tus sue\u00f1os</span>\n          <h2>Encuentra, comprende y solicita becas con una gu\u00eda clara y visual.</h2>\n          <p class=\"lead\">\n            Esta aplicaci\u00f3n re\u00fane el contenido del prototipo VAPA en una experiencia\n            web moderna: inicio, gu\u00eda paso a paso, fuentes confiables, documentos,\n            seguimiento y consejos para completar tu solicitud.\n          </p>\n\n          <div class=\"cta-row\">\n            <a class=\"btn btn-primary\" href=\"#intro\">Comenzar</a>\n            <a class=\"btn btn-secondary\" href=\"#buscar\">Explorar becas</a>\n          </div>\n\n          <div class=\"stat-grid\">\n            <article class=\"stat-card\">\n              <strong>8</strong>\n              <span>pasos pr\u00e1cticos</span>\n            </article>\n            <article class=\"stat-card\">\n              <strong>6</strong>\n              <span>\u00e1reas clave</span>\n            </article>\n            <article class=\"stat-card\">\n              <strong>1</strong>\n              <span>experiencia unificada</span>\n            </article>\n          </div>\n        </div>\n\n        <div class=\"phone-stage reveal\">\n          <div class=\"phone phone-left\">\n            <div class=\"phone-notch\"></div>\n            <div class=\"screen welcome-screen\">\n              <div class=\"logo-stack\">\n                <div class=\"mortarboard\">\n                  <span class=\"cap\"></span>\n                  <span class=\"tassel\"></span>\n                </div>\n                <div class=\"welcome-title\">VAPA</div>\n                <p class=\"welcome-subtitle\">Visualiza- aprende- progresa- avanza</p>\n              </div>\n\n              <p class=\"welcome-body\">\n                Encuentra, comprende y solicita becas que impulsen tu futuro.\n              </p>\n\n              <div class=\"phone-actions\">\n                <button class=\"btn btn-primary\" type=\"button\" data-scroll=\"#intro\">Comenzar</button>\n                <button class=\"btn btn-secondary\" type=\"button\" data-scroll=\"#login\">Iniciar sesi\u00f3n</button>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"phone phone-right\">\n            <div class=\"phone-notch\"></div>\n            <div class=\"screen dashboard-screen\">\n              <div class=\"dashboard-head\">\n                <div>\n                  <p class=\"small-label\">Becas</p>\n                  <h3>Tu espacio para crecer</h3>\n                </div>\n                <div class=\"heart\">\u2661</div>\n              </div>\n\n              <div class=\"grid-menu\">\n                <a class=\"menu-card blue\" href=\"#intro\">\n                  <span class=\"menu-icon\">\ud83d\udca1</span>\n                  <strong>Introducci\u00f3n</strong>\n                </a>\n                <a class=\"menu-card green\" href=\"#perfil\">\n                  <span class=\"menu-icon\">\ud83d\udc64</span>\n                  <strong>Define tu perfil</strong>\n                </a>\n                <a class=\"menu-card lilac\" href=\"#buscar\">\n                  <span class=\"menu-icon\">\ud83d\udd0e</span>\n                  <strong>\u00bfD\u00f3nde buscar?</strong>\n                </a>\n                <a class=\"menu-card yellow\" href=\"#documentos\">\n                  <span class=\"menu-icon\">\ud83d\udcc4</span>\n                  <strong>Documentos</strong>\n                </a>\n                <a class=\"menu-card mint\" href=\"#seguimiento\">\n                  <span class=\"menu-icon\">\ud83d\udc51</span>\n                  <strong>\u00bfQu\u00e9 hacer despu\u00e9s?</strong>\n                </a>\n                <a class=\"menu-card sky\" href=\"#solicitud\">\n                  <span class=\"menu-icon\">\ud83d\udcdd</span>\n                  <strong>Completar solicitud</strong>\n                </a>\n              </div>\n\n              <nav class=\"bottom-dock\" aria-label=\"Navegaci\u00f3n inferior\">\n                <a href=\"#inicio\" class=\"dock-item active\">Inicio</a>\n                <a href=\"#buscar\" class=\"dock-item\">Buscar</a>\n                <a href=\"#recursos\" class=\"dock-item\">Recursos</a>\n              </nav>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"content-grid\">\n        <article class=\"panel reveal\" id=\"intro\">\n          <div class=\"panel-head\">\n            <span class=\"section-kicker\">Gu\u00eda VAPA</span>\n            <h3>Introducci\u00f3n</h3>\n          </div>\n          <p class=\"panel-text\">\n            Encontrar y solicitar una beca puede parecer complejo, sobre todo si es la\n            primera vez. VAPA te acompa\u00f1a paso a paso con una ruta clara para que te\n            organices, filtres oportunidades y prepares una solicitud m\u00e1s fuerte.\n          </p>\n          <div class=\"timeline\">\n            <div class=\"step-card\">\n              <span>1</span>\n              <div>\n                <strong>Identifica tu perfil</strong>\n                <p>Pa\u00eds, carrera, promedio, idiomas y objetivos.</p>\n              </div>\n            </div>\n            <div class=\"step-card\">\n              <span>2</span>\n              <div>\n                <strong>Busca en fuentes confiables</strong>\n                <p>Portales oficiales, universidades, fundaciones y organismos.</p>\n              </div>\n            </div>\n            <div class=\"step-card\">\n              <span>3</span>\n              <div>\n                <strong>Realiza una b\u00fasqueda inteligente</strong>\n                <p>Usa palabras clave espec\u00edficas para resultados m\u00e1s \u00fatiles.</p>\n              </div>\n            </div>\n            <div class=\"step-card\">\n              <span>4</span>\n              <div>\n                <strong>Organiza las oportunidades</strong>\n                <p>Guarda requisitos, fechas, enlaces y estado de tu solicitud.</p>\n              </div>\n            </div>\n          </div>\n        </article>\n\n        <article class=\"panel reveal\" id=\"perfil\">\n          <div class=\"panel-head\">\n            <span class=\"section-kicker\">Paso 1</span>\n            <h3>Define tu perfil acad\u00e9mico</h3>\n          </div>\n          <div class=\"profile-form\">\n            <label>\n              Pa\u00eds de residencia\n              <input type=\"text\" id=\"country\" placeholder=\"Ej. Rep\u00fablica Dominicana\" />\n            </label>\n            <label>\n              Carrera o programa\n              <input type=\"text\" id=\"career\" placeholder=\"Ej. Ingenier\u00eda, medicina, dise\u00f1o...\" />\n            </label>\n            <label>\n              Modalidad\n              <select id=\"modality\">\n                <option>Dentro de mi pa\u00eds</option>\n                <option>En el extranjero</option>\n                <option>Ambas opciones</option>\n              </select>\n            </label>\n            <label>\n              Promedio o \u00edndice\n              <input type=\"text\" id=\"score\" placeholder=\"Ej. 3.8 / 4.0\" />\n            </label>\n          </div>\n          <div class=\"profile-note\" id=\"profileResult\">\n            Completa el formulario para obtener una sugerencia de enfoque.\n          </div>\n          <div class=\"profile-chips\">\n            <span>Idiomas</span>\n            <span>Voluntariado</span>\n            <span>Clubes</span>\n            <span>Deportes</span>\n            <span>Proyectos</span>\n          </div>\n        </article>\n      </section>\n\n      <section class=\"panel reveal\" id=\"buscar\">\n        <div class=\"panel-head split\">\n          <div>\n            <span class=\"section-kicker\">Paso 2 y 3</span>\n            <h3>\u00bfD\u00f3nde buscar? y b\u00fasqueda inteligente</h3>\n          </div>\n          <div class=\"search-box\">\n            <input\n              type=\"search\"\n              id=\"scholarshipSearch\"\n              placeholder=\"Busca: MESCYT, ITLA, INTEC, maestr\u00eda...\"\n            />\n          </div>\n        </div>\n\n        <div class=\"quick-filters\" id=\"quickFilters\">\n          <button type=\"button\" class=\"filter-btn active\" data-filter=\"todos\">Todos</button>\n          <button type=\"button\" class=\"filter-btn\" data-filter=\"dominicana\">Dominicana</button>\n          <button type=\"button\" class=\"filter-btn\" data-filter=\"internacional\">Internacional</button>\n          <button type=\"button\" class=\"filter-btn\" data-filter=\"universidad\">Universidad</button>\n          <button type=\"button\" class=\"filter-btn\" data-filter=\"fundacion\">Fundaci\u00f3n</button>\n        </div>\n\n        <div class=\"cards-grid\" id=\"scholarshipGrid\"></div>\n\n        <div class=\"source-row\">\n          <div class=\"source-card blue-soft\">\n            <strong>Fuentes confiables</strong>\n            <p>Portales gubernamentales, ministerios, universidades y organismos reconocidos.</p>\n          </div>\n          <div class=\"source-card green-soft\">\n            <strong>Verifica el dominio</strong>\n            <p>Revisa extensiones como <code>.gob.do</code>, <code>.gov</code>, <code>.edu</code> y <code>.org</code>.</p>\n          </div>\n          <div class=\"source-card lilac-soft\">\n            <strong>Ejemplos de b\u00fasqueda</strong>\n            <p>Becas para ciberseguridad, becas completas, maestr\u00eda en Canad\u00e1, estudiantes dominicanos.</p>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"content-grid\" id=\"documentos\">\n        <article class=\"panel reveal\">\n          <div class=\"panel-head\">\n            <span class=\"section-kicker\">Paso 4 y 5</span>\n            <h3>Documentos necesarios</h3>\n          </div>\n          <p class=\"panel-text\">\n            Prepara todo con anticipaci\u00f3n. Muchas oportunidades se pierden por buscar\n            documentos a \u00faltima hora.\n          </p>\n          <div class=\"checklist\" id=\"docChecklist\"></div>\n        </article>\n\n        <article class=\"panel reveal\">\n          <div class=\"panel-head\">\n            <span class=\"section-kicker\">Carta de motivaci\u00f3n</span>\n            <h3>Estructura sugerida</h3>\n          </div>\n          <div class=\"stack-list\">\n            <div><strong>Encabezado</strong><span>Fecha y nombre de la instituci\u00f3n.</span></div>\n            <div><strong>Saludo</strong><span>Estimado comit\u00e9 de becas.</span></div>\n            <div><strong>Presentaci\u00f3n</strong><span>Qui\u00e9n eres y por qu\u00e9 escribes.</span></div>\n            <div><strong>Motivaci\u00f3n</strong><span>Tus metas, inspiraci\u00f3n y razones.</span></div>\n            <div><strong>Fortalezas</strong><span>Logros, cualidades y experiencia.</span></div>\n            <div><strong>Cierre</strong><span>Agradecimiento y despedida.</span></div>\n          </div>\n        </article>\n      </section>\n\n      <section class=\"content-grid\" id=\"seguimiento\">\n        <article class=\"panel reveal\">\n          <div class=\"panel-head\">\n            <span class=\"section-kicker\">Paso 6 y 7</span>\n            <h3>Completa la solicitud y guarda el comprobante</h3>\n          </div>\n          <div class=\"stack-list\">\n            <div><strong>Lee las instrucciones</strong><span>No dejes espacios vac\u00edos ni env\u00edes archivos incorrectos.</span></div>\n            <div><strong>Revisa ortograf\u00eda</strong><span>Cuida tu redacci\u00f3n antes de enviar.</span></div>\n            <div><strong>Guarda el registro</strong><span>Anota folio, correo de confirmaci\u00f3n y fecha l\u00edmite.</span></div>\n            <div><strong>Haz seguimiento</strong><span>Revisa correo, portal y redes oficiales.</span></div>\n          </div>\n        </article>\n\n        <article class=\"panel reveal\" id=\"solicitud\">\n          <div class=\"panel-head\">\n            <span class=\"section-kicker\">Paso 8</span>\n            <h3>No te limites a una sola beca</h3>\n          </div>\n          <p class=\"panel-text\">\n            Aplica a varias oportunidades al mismo tiempo, siempre que cumplas los\n            requisitos. En VAPA te recordamos que la constancia, la preparaci\u00f3n y el\n            liderazgo tambi\u00e9n abren puertas.\n          </p>\n          <div class=\"tag-cloud\">\n            <span>Universidades</span>\n            <span>Fundaciones</span>\n            <span>Empresas privadas</span>\n            <span>Organizaciones sin fines de lucro</span>\n            <span>Bibliotecas</span>\n            <span>Peri\u00f3dicos locales</span>\n          </div>\n        </article>\n      </section>\n\n      <section class=\"panel reveal\" id=\"recursos\">\n        <div class=\"panel-head split\">\n          <div>\n            <span class=\"section-kicker\">Recursos</span>\n            <h3>Tu plan r\u00e1pido de acci\u00f3n</h3>\n          </div>\n          <div class=\"mini-badge\">Disponible para m\u00f3vil y escritorio</div>\n        </div>\n        <div class=\"action-grid\">\n          <article>\n            <strong>1. Organiza</strong>\n            <p>Anota becas, fechas, requisitos y estado en una sola vista.</p>\n          </article>\n          <article>\n            <strong>2. Prepara</strong>\n            <p>Re\u00fane expediente, CV, cartas y certificados antes de postular.</p>\n          </article>\n          <article>\n            <strong>3. Env\u00edo</strong>\n            <p>Completa la solicitud con calma y guarda el comprobante.</p>\n          </article>\n          <article>\n            <strong>4. Da seguimiento</strong>\n            <p>Revisa correos, portales y convocatorias complementarias.</p>\n          </article>\n        </div>\n      </section>\n    </main>\n\n    <footer class=\"footer\" id=\"login\">\n      <div>\n        <p class=\"eyebrow\">VAPA</p>\n        <strong>Si es posible para otros, es posible para ti.</strong>\n      </div>\n      <a class=\"btn btn-secondary\" href=\"#inicio\">Volver arriba</a>\n    </footer>\n\n    <script>const scholarships = [\n  {\n    title: \"Becas MESCyT\",\n    region: \"dominicana\",\n    type: \"Gobierno\",\n    level: \"Licenciatura\",\n    description:\n      \"Opciones para estudios nacionales e internacionales con apoyo institucional.\",\n  },\n  {\n    title: \"Beca Tu Futuro\",\n    region: \"dominicana\",\n    type: \"Programa oficial\",\n    level: \"Pregrado\",\n    description:\n      \"Convocatorias enfocadas en estudiantes dominicanos con alto potencial acad\u00e9mico.\",\n  },\n  {\n    title: \"ITLA\",\n    region: \"dominicana\",\n    type: \"Universidad\",\n    level: \"T\u00e9cnico / Grado\",\n    description:\n      \"Oportunidades tecnol\u00f3gicas como ciberseguridad, software y \u00e1reas STEM.\",\n  },\n  {\n    title: \"INTEC\",\n    region: \"dominicana\",\n    type: \"Universidad\",\n    level: \"Licenciatura\",\n    description:\n      \"Becas y ayudas para carreras de alto rendimiento acad\u00e9mico y liderazgo.\",\n  },\n  {\n    title: \"Canad\u00e1 para latinoamericanos\",\n    region: \"internacional\",\n    type: \"Internacional\",\n    level: \"Maestr\u00eda\",\n    description:\n      \"Convocatorias para posgrado con enfoque en investigaci\u00f3n, ciencia y tecnolog\u00eda.\",\n  },\n  {\n    title: \"Fondos de liderazgo\",\n    region: \"fundacion\",\n    type: \"Fundaci\u00f3n\",\n    level: \"Pregrado\",\n    description:\n      \"Apoyos que valoran voluntariado, deportes, clubes y compromiso social.\",\n  },\n];\n\nconst docs = [\n  \"R\u00e9cord o expediente acad\u00e9mico\",\n  \"Copia de documento de identidad o pasaporte\",\n  \"Curr\u00edculum vitae actualizado\",\n  \"Carta de motivaci\u00f3n\",\n  \"Cartas de recomendaci\u00f3n\",\n  \"Certificados de idiomas, si aplica\",\n  \"Certificados de actividades extracurriculares\",\n  \"Ensayos o proyectos personales, cuando se soliciten\",\n];\n\nconst scholarshipGrid = document.querySelector(\"#scholarshipGrid\");\nconst searchInput = document.querySelector(\"#scholarshipSearch\");\nconst quickFilters = document.querySelector(\"#quickFilters\");\nconst docChecklist = document.querySelector(\"#docChecklist\");\nconst profileResult = document.querySelector(\"#profileResult\");\n\nlet activeFilter = \"todos\";\n\nfunction renderScholarships() {\n  const query = (searchInput.value || \"\").toLowerCase().trim();\n\n  const filtered = scholarships.filter((item) => {\n    const matchesFilter = activeFilter === \"todos\" || item.region === activeFilter;\n    const matchesQuery =\n      !query ||\n      `${item.title} ${item.type} ${item.level} ${item.description}`.toLowerCase().includes(query);\n    return matchesFilter && matchesQuery;\n  });\n\n  scholarshipGrid.innerHTML = filtered\n    .map(\n      (item) => `\n        <article class=\"scholarship-card reveal\">\n          <div class=\"meta-row\">\n            <span>${item.region}</span>\n            <span>${item.type}</span>\n            <span>${item.level}</span>\n          </div>\n          <h4>${item.title}</h4>\n          <p>${item.description}</p>\n        </article>\n      `,\n    )\n    .join(\"\");\n\n  if (!filtered.length) {\n    scholarshipGrid.innerHTML = `\n      <article class=\"scholarship-card reveal\" style=\"grid-column: 1 / -1;\">\n        <h4>No encontramos coincidencias</h4>\n        <p>Prueba con otro t\u00e9rmino, por ejemplo: MESCyT, ITLA, INTEC o maestr\u00eda.</p>\n      </article>\n    `;\n  }\n}\n\nfunction renderDocs() {\n  docChecklist.innerHTML = docs\n    .map(\n      (item, index) => `\n        <label class=\"checklist-item reveal\">\n          <input type=\"checkbox\" ${index < 2 ? \"checked\" : \"\"} />\n          <p>${item}</p>\n        </label>\n      `,\n    )\n    .join(\"\");\n}\n\nfunction updateProfileResult() {\n  const country = document.querySelector(\"#country\").value.trim();\n  const career = document.querySelector(\"#career\").value.trim();\n  const modality = document.querySelector(\"#modality\").value;\n  const score = document.querySelector(\"#score\").value.trim();\n\n  const pieces = [];\n  if (country) pieces.push(`Pa\u00eds: <strong>${country}</strong>`);\n  if (career) pieces.push(`Carrera: <strong>${career}</strong>`);\n  if (score) pieces.push(`Promedio: <strong>${score}</strong>`);\n\n  const focus =\n    modality === \"En el extranjero\"\n      ? \"Te conviene priorizar convocatorias internacionales, programas de intercambio y maestr\u00edas.\"\n      : modality === \"Dentro de mi pa\u00eds\"\n        ? \"Te conviene priorizar ministerios, universidades y fundaciones nacionales.\"\n        : \"Puedes combinar convocatorias nacionales e internacionales para ampliar tus opciones.\";\n\n  profileResult.innerHTML = `\n    <div>${pieces.join(\" \u00b7 \") || \"Completa los campos para personalizar tu ruta.\"}</div>\n    <div style=\"margin-top: 8px;\">${focus}</div>\n  `;\n}\n\nfunction bindNavButtons() {\n  document.querySelectorAll(\"[data-scroll]\").forEach((button) => {\n    button.addEventListener(\"click\", () => {\n      const target = document.querySelector(button.dataset.scroll);\n      target?.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n    });\n  });\n}\n\nfunction bindRevealOnScroll() {\n  const observer = new IntersectionObserver(\n    (entries) => {\n      entries.forEach((entry) => {\n        if (entry.isIntersecting) {\n          entry.target.classList.add(\"reveal\");\n          observer.unobserve(entry.target);\n        }\n      });\n    },\n    { threshold: 0.12 },\n  );\n\n  document.querySelectorAll(\".panel, .stat-card, .phone, .scholarship-card, .source-card, .action-grid article, .step-card, .checklist-item\")\n    .forEach((node) => observer.observe(node));\n}\n\nquickFilters.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\".filter-btn\");\n  if (!button) return;\n\n  activeFilter = button.dataset.filter;\n  document.querySelectorAll(\".filter-btn\").forEach((item) => item.classList.remove(\"active\"));\n  button.classList.add(\"active\");\n  renderScholarships();\n});\n\nsearchInput.addEventListener(\"input\", renderScholarships);\n\n[\"country\", \"career\", \"modality\", \"score\"].forEach((id) => {\n  document.querySelector(`#${id}`).addEventListener(\"input\", updateProfileResult);\n  document.querySelector(`#${id}`).addEventListener(\"change\", updateProfileResult);\n});\n\nrenderScholarships();\nrenderDocs();\nupdateProfileResult();\nbindNavButtons();\nbindRevealOnScroll();\n</script>\n  </body>\n</html>\n";

export default {
  async fetch() {
    return new Response(html, {
      headers: { 'content-type': 'text/html; charset=utf-8' },
    });
  },
};
